const missing = new Set();

export function t(key, lang = current) {
  const entry = DICT[key];
  if (!entry) return key;
  const value = entry[lang];
  if (value) return value;
  missing.add(`${key}:${lang}`);
  return entry.en;
}

let current = "en";

export function currentLang() { return current; }

export function applyLang(lang, { root = document } = {}) {
  const next = LANGS.includes(lang) ? lang : "en";
  current = next;
  // The attribute a screen reader reads before it reads a single word.
  //
  // This used to be `root.documentElement.lang = next`, which only works when
  // root is the document. Callers that pass an Element — the MutationObserver
  // that re-applies the language to markup app.js injects after init() — got
  // `undefined.lang = "th"`, a TypeError thrown on the line BEFORE the
  // querySelectorAll below. The translation loop never ran, and the observer
  // silently did nothing on every runtime-rendered view. An Element has no
  // documentElement; its ownerDocument is the one that does.
  const doc = root.nodeType === 9 ? root : root.ownerDocument;
  if (doc && doc.documentElement) doc.documentElement.lang = next;

  // The root itself has to be considered, not only its descendants.
  // querySelectorAll never matches the element it is called on, and that is
  // exactly the shape app.js produces: renderCorrespondence builds with
  // createElement + appendChild one node at a time, so the MutationObserver
  // receives each node as its own mutation record and the node handed to
  // applyLang IS the <p data-i18n="...">. Searching descendants of it returned
  // an empty list every time, so every runtime-rendered paragraph stayed
  // English while the page-level call looked perfectly healthy.
  const self = root.nodeType === 1 && root.matches("[data-i18n], [data-i18n-html]") ? [root] : [];
  const inRoot = (sel) => [...self.filter((el) => el.matches(sel)), ...root.querySelectorAll(sel)];

  for (const el of inRoot("[data-i18n]")) {
    const key = el.dataset.i18n;
    const attr = el.dataset.i18nAttr;      // e.g. "aria-label" or "placeholder"
    if (attr) { el.setAttribute(attr, t(key, next)); continue; }
    // Never textContent an element that has element children. That deletes
    // them, and the children here are not decoration — <span id="corr-method">
    // is written by app.js at render, so switching language removed the node
    // the render was about to fill, threw inside renderCorrespondence, and took
    // the whole Record view down with it. Found by the verifier, not by reading.
    if (el.firstElementChild) {
      if (!el.dataset.i18nSkip) {
        missing.add(`${key}: has ${el.children.length} child element(s) — not textContent`);
      }
      continue;
    }
    el.textContent = t(key, next);
  }
  for (const el of inRoot("[data-i18n-html]")) {
    el.innerHTML = t(el.dataset.i18nHtml, next);
  }
  // A dictionary entry that declares isHtml carries its emphasis with it. It is
  // set through innerHTML, which means the translation is authored here and not
  // scraped from the page — the tag is part of the string, not an accident of
  // whatever the English happened to be wrapped in.
  for (const el of inRoot("[data-i18n]")) {
    const entry = DICT[el.dataset.i18n];
    if (entry && entry.isHtml) el.innerHTML = entry[next] || entry.en;
  }

  for (const button of root.querySelectorAll("[data-lang-set]")) {
    const on = button.dataset.langSet === next;
    button.setAttribute("aria-pressed", String(on));
  }
  try { localStorage.setItem("ascn-lang", next); } catch { /* private mode */ }
  return next;
}

/* Read the language from three places, in order of explicitness:
   ?lang= wins (so a link can carry a language), then the reader's last
   choice, then English. Never guess from the browser — a reader who chose
   Thai last week does not want English back because their OS changed. */
export function initLang() {
  const q = new URLSearchParams(location.search).get("lang");
  let stored = null;
  try { stored = localStorage.getItem("ascn-lang"); } catch { /* private mode */ }
  return applyLang(q || stored || "en");
}

export function missingTranslations() { return [...missing]; }